use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn element_greater(x: i8, y: i8) -> bool {
    (x as int) > (y as int)
}

spec fn vec_greater(a: Seq<i8>, b: Seq<i8>) -> Seq<bool>
    recommends
        a.len() == b.len(),
    decreases a.len(),
{
    if a.len() == 0 {
        Seq::<bool>::empty()
    } else {
        vec_greater(a.drop_last(), b.drop_last())
            .push(element_greater(a.last(), b.last()))
    }
}

fn greater(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
    requires
        a.len() == b.len(),
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i && i < a.len() ==> 
            result[i] == element_greater(a[i], b[i]),
{
    let mut result_vec = Vec::new();
    let mut i: usize = 0;
    
    while i < a.len()
        invariant
            0 <= i <= a.len(),
            result_vec.len() == i,
            forall|j: int| 0 <= j && j < i ==>
                result_vec[j] == element_greater(a[j], b[j]),
    {
        let a_elem = a[i];
        let b_elem = b[i];
        let is_greater = a_elem > b_elem;
        result_vec.push(is_greater);
        i = i + 1;
    }
    
    result_vec
}

}
